package com.bank.gateway;

import org.springframework.stereotype.Service;
import java.math.BigDecimal;

// The SAME source compiles under both Maven and Gradle — the build tool
// does not change the application code, only how it is assembled.
@Service
public class PaymentService {

    // Compute a 0.5% gateway fee on a payment amount. Money uses BigDecimal.
    public BigDecimal gatewayFee(BigDecimal amount) {
        if (amount == null || amount.signum() <= 0) {
            throw new IllegalArgumentException("amount must be positive");
        }
        return amount.multiply(new BigDecimal("0.005"))
                     .setScale(2, java.math.RoundingMode.HALF_UP);
    }
}
